#!/usr/bin/env bash
set -euo pipefail

_LIB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=bin/_agents/_lib.sh
source "$_LIB_DIR/_lib.sh"

RULES_ROOT_DIR="$1"
SKILLS_ROOT_DIR="$2"
BASE_DIR="${3:-.}"
EXCLUSIVE_ROOT_DIR="${4:-}"
# If BASE_DIR is empty (passed as ""), default to .
if [[ -z "$BASE_DIR" ]]; then
  BASE_DIR="."
fi

CLEAN="${5:-false}"

RULES_DIR="$BASE_DIR/.cursor/rules"
SKILLS_DIR="$BASE_DIR/.cursor/skills"
MANIFEST="$BASE_DIR/.cursor/.agentx-manifest"

# With --clean, remove files generated by the previous run (per the
# manifest) before regenerating. Hand-added files aren't in the manifest,
# so they are preserved.
if [[ "$CLEAN" == "true" ]]; then
  manifest_clean "$MANIFEST" "$BASE_DIR" "$RULES_DIR" "$SKILLS_DIR"
fi

mkdir -p "$RULES_DIR"
mkdir -p "$SKILLS_DIR"
manifest_init "$MANIFEST"

# Helper function to process rules
process_rules() {
  local src_dir="$1"
  
  if [[ ! -d "$src_dir" ]]; then return; fi
  
  while IFS= read -r -d '' rule_file; do
    local rel_path rel_dir filename target_dir output_file
    local trigger description
    rel_path="${rule_file#"$src_dir"/}"
    rel_dir="$(dirname "$rel_path")"
    filename="$(basename "$rel_path" .md)"

    target_dir="$RULES_DIR/$rel_dir"
    mkdir -p "$target_dir"
    output_file="$target_dir/${filename}.mdc"

    trigger="$(fm_field "$rule_file" trigger)"
    trigger="${trigger:-always}"
    description="$(fm_field "$rule_file" description)"

    {
      echo "---"
      case "$trigger" in
        always)
          echo "alwaysApply: true"
          ;;
        auto)
          [[ -n "$description" ]] && echo "description: $description"
          echo "alwaysApply: false"
          ;;
        off)
          echo "alwaysApply: false"
          ;;
        *)
          echo "Error: unknown trigger '$trigger' in $rule_file" >&2
          exit 1
          ;;
      esac
      echo "---"
      echo ""
      fm_body "$rule_file"
    } > "$output_file"
    record_generated "$MANIFEST" "$BASE_DIR" "$output_file"
  done < <(find "$src_dir" -name "*.md" -print0)
}

# Helper function to process skills
process_skills() {
  local src_dir="$1"
  
  if [[ ! -d "$src_dir" ]]; then return; fi
  
  # Find all SKILL.md files in subdirectories
  while IFS= read -r -d '' skill_file; do
    local skill_name target_skill_dir
    # Get the parent directory name as the skill name
    skill_name="$(basename "$(dirname "$skill_file")")"
    # Cursor discovers skills at .cursor/skills/<name>/SKILL.md
    target_skill_dir="$SKILLS_DIR/${skill_name}"
    mkdir -p "$target_skill_dir"

    cat "$skill_file" > "$target_skill_dir/SKILL.md"
    record_generated "$MANIFEST" "$BASE_DIR" "$target_skill_dir/SKILL.md"
  done < <(find "$src_dir" -name "SKILL.md" -print0)
}

# 1. Process Core Rules
process_rules "$RULES_ROOT_DIR"

# 2. Process Core Skills
process_skills "$SKILLS_ROOT_DIR"

# 3. Process Exclusive content if provided
if [[ -n "$EXCLUSIVE_ROOT_DIR" ]] && [[ -d "$EXCLUSIVE_ROOT_DIR" ]]; then
  echo "Applying exclusive content from: $EXCLUSIVE_ROOT_DIR"
  process_rules "$EXCLUSIVE_ROOT_DIR/rules"
  process_skills "$EXCLUSIVE_ROOT_DIR/skills"
fi

echo "Cursor generation complete."
